## 📋 Suggested Refactor – Minimal Secure Baseline

Below is a **drop‑in replacement** for `app.js` that addresses the high‑risk items while staying lightweight. You can copy‑paste it, run `npm install` for the new dependencies, and the app will be considerably more secure.

```js
// app.js – Secure baseline
// ------------------------------------------------
// 1️⃣  Install needed packages first:
//    npm i express helmet cors express-rate-limit dotenv morgan
// ------------------------------------------------

require('dotenv').config();                // Load .env (never commit this file)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ------------------------------------------------
// Middleware (security first)
// ------------------------------------------------
app.use(helmet());                         // Sets many security headers
app.use(cors({                             
  origin: process.env.CORS_ORIGIN?.split(',') || [], // whitelist e.g. "https://myapp.com"
  methods: ['GET','POST','PUT','DELETE'],
  credentials: true,
}));
app.use(express.json());                  // Body parser for JSON payloads
app.use(morgan('combined'));              // Structured request logging

// Rate limiting: 100 requests per 15‑min window per IP
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, try again later.' },
});
app.use('/users', apiLimiter);            // Apply only where needed (example)

// ------------------------------------------------
// Simple in‑memory "auth" stub (replace with real JWT / session)
// ------------------------------------------------
function requireAuth(req, res, next) {
  // For demo: expect an Authorization header: "Bearer secret-token"
  const auth = req.headers.authorization || '';
  const token = auth.replace(/^Bearer\s+/i, '');
  if (token !== process.env.API_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

// ------------------------------------------------
// Routes
// ------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint – only authenticated callers can see user data
app.get('/users', requireAuth, (req, res) => {
  // In a real app you'd fetch from a DB with prepared statements.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ------------------------------------------------
// Centralised error handling (hide stack traces in prod)
// ------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err);                     // Still log the details for dev/ops
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;
  res.status(status).json({ error: message });
});

// ------------------------------------------------
// Server start – honour PORT env var, default to 3000
// ------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

