### 3.2. Enforce Authentication & Authorization

> **Goal:** Never expose user data (or any sensitive resource) without verifying the requester’s identity and permissions.

```js
// auth.js (new file)
const jwt = require('jsonwebtoken');
const createError = require('http-errors');

const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return next(createError(401, 'Missing Authorization header'));

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;   // attach user info to request
    next();
  } catch (err) {
    next(createError(401, 'Invalid token'));
  }
};

module.exports = { authenticate };
```

```js
// app.js – protect the /users endpoint
const { authenticate } = require('./auth');

// Example role‑based check (A01)
const authorize = (allowedRoles) => (req, res, next) => {
  if (!req.user || !allowedRoles.includes(req.user.role)) {
    return next(require('http-errors')(403, 'Forbidden'));
  }
  next();
};

app.get('/users', authenticate, authorize(['admin']), (req, res) => {
  // In a real app this would query a DB with parameterised queries.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Why:**  
* Guarantees that only authenticated users (and only those with the right role) can read the `/users` list.  
* Protects against **A01 – Broken Access Control** and **A07 – Authentication Failures**.

