.env
.env.*   # ignore any .env.* (including .env.test, .env.local, etc.) in production
```

### 2️⃣ Centralise configuration in a dedicated module

Create a small `config.js` (or `config/index.js`) that abstracts how values are obtained. All other modules import from this single place.

```js
// config.js – a thin wrapper that prefers a secret‑manager first,
// then falls back to process.env (which may be populated by a container/orchestrator).
const { readFileSync } = require('fs');
const logger = require('pino')();

function getSecretFromAws(secretName) {
  // Example using AWS SDK v3 – replace with your preferred manager
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  return client.send(new GetSecretValueCommand({ SecretId: secretName }))
    .then(data => data.SecretString)
    .catch(err => {
      logger.error({ err, secretName }, 'Failed to fetch secret from AWS Secrets Manager');
      throw err;
    });
}

// Example – load a secret lazily, cache the promise.
let cachedDbUrl;
function getDatabaseUrl() {
  if (cachedDbUrl) return cachedDbUrl;
  // Prefer AWS Secrets Manager, fallback to env var.
  const secretName = process.env.AWS_DB_SECRET_NAME;   // e.g. "prod/app-db"
  if (secretName) {
    cachedDbUrl = getSecretFromAws(secretName);
  } else {
    // Direct env var (e.g., injected by K8s secret or Docker ENV)
    if (!process.env.DATABASE_URL) {
      throw new Error('DATABASE_URL is not defined');
    }
    cachedDbUrl = Promise.resolve(process.env.DATABASE_URL);
  }
  return cachedDbUrl;
}

// Export a *promise* so callers can `await getDatabaseUrl()`
module.exports = {
  getDatabaseUrl,
  // Add other getters as needed.
};
```

**Why this helps**

* **Single source of truth** – any future secret‑manager change only touches `config.js`.
* **Lazy loading** – the secret is fetched only when needed, which is useful for server‑less or cold‑start environments.
* **Clear fallback** – you can still run locally by setting environment variables in your shell or a **local `.env.example`** file (never committed).

### 3️⃣ If you must use a `.env` file for local development, protect it with `dotenv-safe`

`dotenv-safe` forces the presence of an **`.env.example`** file that lists the required variable names, ensuring you never accidentally ship a real secret:

```bash
