    return JSON.parse(payload);
  } catch (_) {
    return payload; // plain string fallback
  }
}

/**
 * Export a ready‑to‑use object with the secrets our app needs.
 *
 * Example secret "myapp/database" => { username: "...", password: "...", host: "...", ... }
 */
async function getAppSecrets() {
  const [
    dbSecret,
    stripeSecret,
    anthropicSecret,
    logfireToken,
  ] = await Promise.all([
    loadSecret(process.env.AWS_SECRET_ARN_DATABASE),   // e.g. arn:aws:secretsmanager:eu-west-1:123456789012:secret:myapp/database-abc123
    loadSecret(process.env.AWS_SECRET_ARN_STRIPE),
    loadSecret(process.env.AWS_SECRET_ARN_ANTHROPIC),
    loadSecret(process.env.AWS_SECRET_ARN_LOGFIRE),
  ]);

  return {
    // Database config (example for pg)
    DB: {
      connectionString: dbSecret.url,      // or dbSecret.DATABASE_URL
    },
    STRIPE_KEY: stripeSecret,
    ANTHROPIC_KEY: anthropicSecret,
    LOGFIRE_TOKEN: logfireToken,
  };
}

module.exports = { getAppSecrets };
```

**How to use it in `app.js`**

```js
