  const secrets = await getAppSecrets();

  // Example: inject into process.env for downstream libraries
  process.env.DATABASE_URL   = secrets.DB.connectionString;
  process.env.STRIPE_SECRET_KEY = secrets.STRIPE_KEY;
  process.env.ANTHROPIC_API_KEY = secrets.ANTHROPIC_KEY;
  process.env.LOGFIRE_TOKEN     = secrets.LOGFIRE_TOKEN;

  // The rest of your server code (express setup) can stay unchanged.
  const PORT = process.env.PORT || 3000;
