## 5️⃣  Port‑able Wrapper (Works with any provider)

If you may switch clouds, you can write a thin abstraction that picks the provider based on an environment variable:

```js
// src/secretsProvider.js
const providers = {
  aws: async (name) => {
    const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const secret = await client.send(new GetSecretValueCommand({ SecretId: name }));
    return JSON.parse(secret.SecretString);
  },

  gcp: async (name) => {
    const { SecretManagerServiceClient } = require("@google-cloud/secret-manager");
    const client = new SecretManagerServiceClient();
    const [version] = await client.accessSecretVersion({ name });
    return JSON.parse(version.payload.data.toString());
  },

  // add vault, azure, etc.
};

async function getSecret(name) {
  const provider = process.env.SECRET_PROVIDER?.toLowerCase() ?? "aws";
  if (!providers[provider]) {
    throw new Error(`Unsupported secret provider: ${provider}`);
  }
  return providers[provider](name);
}

module.exports = { getSecret };
```

Now the same code works regardless of the underlying cloud, simply by setting `SECRET_PROVIDER=aws|gcp|vault` and the appropriate connection variables.

