> **NOTE:** This example assumes you will later add a database layer and more routes. Keep the security middleware at the top of the middleware stack – before any route definitions.

```js
// app.js – secure baseline for an Express API
require('dotenv').config();               // <-- load .env (port, JWT secret, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');       // for auth demo
const morgan = require('morgan');          // request logging

const app = express();

// -----------------------------------------------------
// 1️⃣ Global security middleware (run first)
// -----------------------------------------------------

// Helmet sets dozens of secure HTTP headers (CSP, HSTS, X‑XSS‑Protection, …)
app.use(helmet());

// CORS – lock down to trusted origins (adjust as needed)
const allowedOrigins = (process.env.CORS_ORIGINS || '').split(',')
  .filter(Boolean);
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser requests (e.g., Postman) when origin is undefined
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      return callback(new Error('Not allowed by CORS'));
    },
    credentials: true,
  })
);

// Rate limiting – 100 requests per 15‑min window per IP (tune for your use‑case)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Body parser with size limit (prevents large payload DoS)
app.use(express.json({ limit: '10kb' }));

// Request logging (skip in test env)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// -----------------------------------------------------
// 2️⃣ Helper: JWT authentication middleware
// -----------------------------------------------------
function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;   // payload can hold { sub, role, … }
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// -----------------------------------------------------
// 3️⃣ Routes – keep them after the security stack
// -----------------------------------------------------

// Health endpoint – avoid leaking internal details (no stack trace, no server version)
app.get('/health', (req, res) => {
  // Optionally omit timestamp if you don’t need it for monitoring
  res.json({ status: 'ok' });
});

// Protected route example – only authenticated users can see the list
app.get('/users', authenticateJWT, (req, res) => {
  // In a real app, pull from a DB with proper access controls
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// -----------------------------------------------------
// 4️⃣ Central error handler (no stack traces in prod)
// -----------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err); // log to console / winston in prod

  const status = err.status || 500;
  const response = {
    error:
      process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : err.message,
  };
  res.status(status).json(response);
});

// -----------------------------------------------------
// 5️⃣ Server start – use env vars, support HTTPS behind a proxy
// -----------------------------------------------------
const PORT = process.env.PORT || 3000;

// If you run behind a reverse proxy that terminates TLS (NGINX, Cloudflare, etc.):
//   * set `app.set('trust proxy', 1);` so Express knows the original IP
//   * optionally enforce HTTPS redirects.
if (process.env.ENFORCE_HTTPS === 'true') {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) return next();
    // redirect to same URL with https
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### How to integrate the above into your repo

1. **Add required dependencies** (run once):
   ```bash
   npm i helmet cors express-rate-limit jsonwebtoken morgan dotenv
   ```
2. **Create a `.env` file** (never commit secrets):
   ```
   PORT=3000
   NODE_ENV=production
   JWT_SECRET=your‑strong‑random‑secret‑here
   CORS_ORIGINS=https://my‑frontend.com,https://admin.my‑app.com
   ENFORCE_HTTPS=true
   ```
3. **Update any test scripts** to import the app without automatically starting a server (the above file already does that).

