```

### 3️⃣ Pull secrets at start‑up from a manager (example uses **AWS Secrets Manager**)

1. **Add the AWS SDK**  

   ```bash
   npm i @aws-sdk/client-secrets-manager
   ```

2. **Create a helper (`secrets.js`)** that fetches and caches the secrets.  
   This runs once when the process boots, then puts the values onto `process.env` **after** we’ve already loaded the safe `.env`.

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Load a secret (JSON‑encoded) from AWS Secrets Manager and merge into process.env.
 * @param {string} secretName  The ARN or name of the secret in AWS.
 */
async function loadSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);

  // Secrets can be stored as plain text or JSON.
  let secretObject;
  try {
    secretObject = JSON.parse(response.SecretString);
  } catch (_) {
    // Not JSON – treat the whole string as a single value called "value"
    secretObject = { value: response.SecretString };
  }

  // Merge each key into process.env (won’t overwrite existing non‑secret env vars)
  for (const [key, val] of Object.entries(secretObject)) {
    if (!process.env[key]) {
      process.env[key] = val;
    }
  }
}

/**
 * Load all required secrets – call this before you start the Express server.
 */
async function initSecrets() {
  // List every secret the app needs.  Keep the list short & explicit.
  const required = [
    // Example: "my-app/jwt-secret", "my-app/db-credentials"
    'my-app/jwt-secret',          // contains { JWT_SECRET: "very‑long‑random‑string" }
    'my-app/db-credentials',      // contains { DATABASE_URL: "postgres://…" }
    // Add more secret identifiers as needed.
  ];

  for (const name of required) {
    await loadSecret(name);
  }
}

module.exports = { initSecrets };
```

3. **Wire it into `app.js`** (only in non‑test environments)

```js
// app.js – after the `require('dotenv').config();` line
if (process.env.NODE_ENV !== 'test') {
  const { initSecrets } = require('./secrets');
  // Immediately‑invoked async function to halt startup until secrets are ready.
  (async () => {
    try {
      await initSecrets();
      console.log('✅ Secrets loaded from AWS Secrets Manager');
    } catch (e) {
      console.error('❌ Failed to load secrets:', e);
      process.exit(1); // fail fast – never start server with missing secrets
    }
  })();
}
```

> **Tip:** If you use a different cloud provider, replace the AWS SDK calls with the provider’s SDK (`@google-cloud/secret-manager`, `@azure/keyvault-secrets`, etc.). The pattern (load safe env, then fetch secrets, then start server) stays the same.

### 4️⃣ How to run locally without a cloud secret manager

* Keep a **local `.env.local`** (git‑ignored) that mirrors the shape of the secret JSON objects.  
* Modify `initSecrets()` to fallback to reading that file when `process.env.AWS_SDK_LOAD_CONFIG` is not set, or simply skip the fetch when `process.env.NODE_ENV === 'development'`.

```js
if (process.env.NODE_ENV === 'development') {
  // Example: load a local JSON file that mimics the secret structure
  const devSecrets = require('./secrets.dev.json'); // { JWT_SECRET: "...", DATABASE_URL: "..." }
  Object.assign(process.env, devSecrets);
}
```

