// secrets.js
// Load selected secrets from AWS Secrets Manager and inject them into process.env
// ------------------------------------------------------------
//   npm i @aws-sdk/client-secrets-manager
// ------------------------------------------------------------
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const REGION = process.env.AWS_REGION || 'us-east-1';
const client = new SecretsManagerClient({ region: REGION });

/**
 * @param {string[]} secretIds – IDs or ARNs of the secrets you want to fetch.
 * @returns {Promise<void>}
 */
async function loadSecrets(secretIds) {
  for (const id of secretIds) {
    try {
      const data = await client.send(new GetSecretValueCommand({ SecretId: id }));
      // Secrets Manager returns a JSON string or plain string
      const secretString = data.SecretString;
      let parsed;
      try {
        parsed = JSON.parse(secretString);
      } catch {
        // Not JSON – treat as a single key/value pair where the secret name is the key
        parsed = { [id]: secretString };
      }

      // Flatten into process.env (overwrite only if not already set)
      for (const [key, value] of Object.entries(parsed)) {
        if (!process.env[key]) {
          process.env[key] = value;
        }
      }
    } catch (err) {
      console.error(`❌ Unable to load secret ${id}:`, err);
      // In production you may want to fail fast:
      // throw err;
    }
  }
}

module.exports = { loadSecrets };
```

Then **boot‑strap** the server:

```js
// server.js   <-- new entry point (instead of `node app.js`)
