## 2. Recommendations & Code Examples

Below is a **minimal but production‑ready** rewrite that demonstrates how to address each of the above concerns. You can adopt it piece‑by‑piece, but for clarity the example puts everything together.

```js
/**
 * app.js – Hardened Express server
 *
 * Key security measures implemented:
 *  • Helmet (secure HTTP headers)
 *  • Rate limiting (express-rate-limit)
 *  • CORS with whitelist
 *  • Input validation (Joi) – illustrated on a future POST /users route
 *  • Authentication (JWT) – middleware skeleton
 *  • Centralised error handling (no stack traces to the client)
 *  • Environment‑driven configuration (port, JWT secret, CORS whitelist)
 *  • Logging (morgan) + request ID (cls-hooked) for traceability
 *  • Graceful shutdown handling
 */

require('dotenv').config();               // <-- loads .env (never commit secrets!)
const express = require('express');
const helmet = require('helmet');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const Joi = require('joi');               // input validation library
const { v4: uuidv4 } = require('uuid');   // request‑id generator

const app = express();

// ---------------------------------------------------------------------------
// 1️⃣ Basic middleware (JSON body parsing, request IDs, logging)
// ---------------------------------------------------------------------------
app.use(express.json());                 // parse JSON bodies for POST/PUT
app.use((req, res, next) => {
  // Attach a unique request ID for logging & correlation
  req.id = uuidv4();
  res.setHeader('X-Request-Id', req.id);
  next();
});
app.use(morgan(':date[iso] :method :url :status :response-time ms - :res[content-length] :req[req-id]', {
  // you can customize the token :req[req-id] if you need more detail
  stream: process.stdout,
}));

// ---------------------------------------------------------------------------
// 2️⃣ Security‑hardening headers
// ---------------------------------------------------------------------------
app.use(helmet());                       // sets dozens of secure headers (CSP, HSTS, etc.)

// ---------------------------------------------------------------------------
// 3️⃣ CORS – restrict to known origins (adjust the whitelist for your environment)
// ---------------------------------------------------------------------------
const whitelist = (process.env.CORS_ORIGINS || '').split(',').filter(Boolean);
const corsOptions = {
  origin: (origin, callback) => {
    // Allow non‑browser tools (e.g., curl, Postman) when origin is undefined
    if (!origin || whitelist.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
};
app.use(cors(corsOptions));

// ---------------------------------------------------------------------------
// 4️⃣ Rate limiting – mitigates brute‑force and DoS attacks
// ---------------------------------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter); // apply only to API routes (prefix later if you like)

// ---------------------------------------------------------------------------
// 5️⃣ Authentication middleware (JWT example)
// ---------------------------------------------------------------------------
function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1]; // Expect "Bearer <token>"
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user; // user payload can contain roles, permissions, etc.
    next();
  });
}

// ---------------------------------------------------------------------------
// 6️⃣ Input validation schema (example for a future POST /users endpoint)
// ---------------------------------------------------------------------------
const createUserSchema = Joi.object({
  name: Joi.string().trim().min(1).max  (100).required(),
  email: Joi.string().email().required(),
  password: Joi.string()
    .min(8)
    .max(128)
    .regex(/[A-Z]/, 'uppercase')
    .regex(/[a-z]/, 'lowercase')
    .regex(/[0-9]/, 'digit')
    .regex(/[\W_]/, 'special')
    .required(),
});

// ---------------------------------------------------------------------------
// 7️⃣ Routes – all real API endpoints should sit under a versioned prefix
// ---------------------------------------------------------------------------
app.get('/health', (req, res) => {
  // No sensitive data, safe to expose
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example of a protected endpoint.
 * In a real system you would likely fetch data from a database,
 * using parameterised queries (to avoid injection) or an ORM.
 */
app.get('/api/v1/users', authenticateJWT, (req, res) => {
  // In production replace the static array with a DB call.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/**
 * Example POST endpoint demonstrating validation + safe handling.
 * Replace the stub with actual persistence logic (e.g., PostgreSQL,
 * MongoDB) using prepared statements or an ORM to prevent injection.
 */
app.post('/api/v1/users', authenticateJWT, (req, res, next) => {
  const { error, value } = createUserSchema.validate(req.body);
  if (error) {
    // Joi returns a detailed error object – we only expose the message.
    return res.status(400).json({ error: error.details[0].message });
  }

  // ----> INSERT INTO users (...) VALUES (...)  (parameterised!)
  // For illustration we just echo back a sanitized object:
  const newUser = {
    id: Date.now(), // placeholder ID – use DB auto‑increment in real code
    name: value.name,
    email: value.email,
  };
  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// 8️⃣ Centralised error handling (never leak stack traces in production)
// ---------------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error for operators
  console.error(`[${new Date().toISOString()}] [${req.id}]`, err);

  // Determine safe status code
  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal server error' : err.message,
  };

  // In non‑production you may want to include err.stack for debugging.
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// ---------------------------------------------------------------------------
// 9️⃣ Server start – configurable port, graceful shutdown
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server listening on port ${PORT}`);
});

// Graceful shutdown (e.g., for Kubernetes, Docker stop)
function shutdown() {
  console.log('🔌 Shutting down gracefully...');
  server.close(() => {
    console.log('🛑 Server closed');
    process.exit(0);
  });
  // If after 10 seconds it's still not closed, force exit
  setTimeout(() => {
    console.error('⚠️ Forced shutdown');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

