require('dotenv').config();               // Load env variables safely
const express = require('express');
const helmet = require('helmet');         // Security headers
const cors = require('cors');             // CORS control
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // Request logging
const jwt = require('jsonwebtoken');     // Example JWT auth
const { body, param, validationResult } = require('express-validator');

const app = express();

// ------------------- Middleware -----------------------------

// Secure HTTP headers
app.use(helmet());

// Enable strong CORS (adjust origin list as needed)
app.use(cors({
  origin: process.env.CORS_ORIGIN?.split(',') || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
}));

// Body parsing (JSON only, limits size)
app.use(express.json({ limit: '10kb' }));

// Request logging (combined format, can be piped to a file or log system)
app.use(morgan('combined'));

// Rate limiting – 100 requests per 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ------------------- Authentication -------------------------

// Simple JWT verification middleware (replace with your own secret/strategy)
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401); // No token -> unauthorized

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token
    req.user = user;                     // Attach user payload
    next();
  });
}

// Example: only admin role can view the full user list
function requireAdmin(req, res, next) {
  if (req.user?.role !== 'admin') {
    return res.sendStatus(403);
  }
  next();
}

// ------------------- Routes ---------------------------------

app.get('/health', (req, res) => {
  // Do not expose internal timestamps unless needed; keep minimal info.
  res.json({ status: 'ok' });
});

/**
 * GET /users
 * • Protected – requires a valid JWT.
 * • Returns only non‑PII fields unless the caller is admin.
 */
app.get('/users', authenticateToken, (req, res) => {
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // If the requester is admin, give full data; otherwise strip e‑mail.
  if (req.user?.role === 'admin') {
    return res.json(allUsers);
  }
  const sanitized = allUsers.map(u => ({ id: u.id, name: u.name }));
  res.json(sanitized);
});

/**
 * Example of a POST endpoint that demonstrates input validation &
 * safe handling to prevent injection.
 */
app.post(
  '/users',
  authenticateToken,
  requireAdmin,
  [
    body('name').trim().isLength({ min: 1, max: 100 }).escape(),
    body('email').isEmail().normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, use a DB with parameterised queries, e.g.:
    // await db.query('INSERT INTO users (name,email) VALUES ($1,$2)', [name,email]);
    const { name, email } = req.body;
    // Simulate created user (id would be generated by DB)
    const newUser = { id: Date.now(), name, email };
    res.status(201).json(newUser);
  }
);

// ------------------- Centralised Error Handler --------------

app.use((err, req, res, next) => {
  // Log the error (avoid sending stack traces to the client)
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ------------------------------------------------------------
// Server start – enforce HTTPS in production (optional)
// ------------------------------------------------------------
