```js
// src/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Returns the secret value as a plain string.
 * If the secret is a JSON object, call JSON.parse() on the result.
 */
async function getSecret(name) {
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);
  // The secret can be stored as a string or binary; we handle the string case.
  return response.SecretString;
}

// Example usage:
async function loadAllRequiredSecrets() {
  const dbUrl = await getSecret('myapp/DATABASE_URL');
  const stripeKey = await getSecret('myapp/STRIPE_SECRET_KEY');
  // assign to process.env for legacy compatibility (optional)
  process.env.DATABASE_URL = dbUrl;
  process.env.STRIPE_SECRET_KEY = stripeKey;
}

module.exports = { loadAllRequiredSecrets };
```

**Integrate at server start (in `app.js`)**

```js
const { loadAllRequiredSecrets } = require('./src/secrets');

(async () => {
  // Load secrets *once* before the server starts listening.
  await loadAllRequiredSecrets();

  // Now you can safely use process.env.DATABASE_URL, etc.
  const db = new Pool({ connectionString: process.env.DATABASE_URL });

  // …rest of your Express setup…
  app.listen(PORT, () => console.log(`Server running on ${PORT}`));
})();
```

### 2️⃣ HashiCorp Vault (HTTP API)

**Install `node-vault`**

```bash
npm install node-vault
```

**Sample helper**

```js
// src/vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'https://vault.mycompany.com',
  token: process.env.VAULT_TOKEN,   // token injected via the orchestrator
});

async function fetchSecret(path) {
  const result = await vault.read(path);
  return result.data;
}

// Example usage:
async function loadSecrets() {
  const db = await fetchSecret('secret/data/myapp/database');
  process.env.DATABASE_URL = db.url;
  const stripe = await fetchSecret('secret/data/myapp/stripe');
  process.env.STRIPE_SECRET_KEY = stripe.key;
}
module.exports = { loadSecrets };
```

### 3️⃣ GCP – Secret Manager

**Install GCP client**

```bash
npm install @google-cloud/secret-manager
```

**Helper**

```js
// src/gcpSecrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function accessSecret(name) {
  const [version] = await client.accessSecretVersion({ name });
  return version.payload.data.toString('utf8');
}

async function loadSecrets() {
  process.env.DATABASE_URL = await accessSecret(
    'projects/PROJECT_ID/secrets/DATABASE_URL/versions/latest'
  );
  process.env.STRIPE_SECRET_KEY = await accessSecret(
    'projects/PROJECT_ID/secrets/STRIPE_SECRET_KEY/versions/latest'
  );
}
module.exports = { loadSecrets };
```

### 4️⃣ Production‑Ready Pattern Summary

| Step | Description |
|------|-------------|
| **a. Remove `.env` from the container image** – Do not copy it in Dockerfiles. |
| **b. Inject short‑lived tokens** – Provide the process with a **cloud‑provider‑IAM** token (e.g., AWS IAM role, GCP service‑account) that has permission to read the secrets. |
| **c. Load secrets at start‑up** – Use one of the helpers above, cache them in memory, and avoid re‑reading on every request. |
| **d. Fail fast** – If any required secret is missing, abort start‑up (`process.exit(1)`). |
| **e. Rotate automatically** – Many secret managers can rotate credentials (e.g., RDS IAM auth). Your code just reads the latest value on each start. |
| **f. Audit** – Enable secret‑manager audit logs; they record which principal accessed which secret. |
| **g. Least‑privilege IAM** – Grant the service account *only* the `GetSecretValue` (or equivalent) permission for the secret paths it truly needs. |

