```js
// config.js
'use strict';

/**
 * Configuration helper that:
 *   1. Loads .env (development only)
 *   2. Retrieves secrets from a cloud secrets manager in production
 *   3. Exposes a single `get(key)` API.
 *
 * Adjust the provider logic to match your environment.
 */

const fs = require('fs');
const path = require('path');

let envLoaded = false;

// Load .env only when the file exists (development)
if (fs.existsSync(path.resolve(__dirname, '.env'))) {
  require('dotenv').config();          // pulls variables into process.env
  envLoaded = true;
}

/**
 * Retrieve a secret value.
 *
 * In production (`NODE_ENV=production`) we fetch from AWS Secrets Manager.
 * In any other environment we read from process.env (already populated by .env).
 */
async function getSecret(key) {
  // 1️⃣ Development / fallback – read from environment variables
  if (!process.env.NODE_ENV || process.env.NODE_ENV !== 'production') {
    if (!process.env[key]) {
      throw new Error(`Missing required environment variable ${key}`);
    }
    return process.env[key];
  }

  // 2️⃣ Production – fetch from AWS Secrets Manager
  const AWS = require('aws-sdk');
  const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

  // Assume secret naming convention: <app-name>/<key>
  const secretId = `${process.env.APP_NAME}/${key}`;

  try {
    const data = await client.getSecretValue({ SecretId: secretId }).promise();
    const secretString = data.SecretString;
    if (!secretString) {
      throw new Error(`Secret ${secretId} is empty`);
    }
    // If the secret is stored as a plain string, return it directly.
    // If it is a JSON object, parse and return the requested field.
    try {
      const parsed = JSON.parse(secretString);
      if (parsed[key]) return parsed[key];
      // If the secret itself is just the value, fall back
      return secretString;
    } catch (_) {
      // Not JSON – straight value
      return secretString;
    }
  } catch (err) {
    console.error(`Failed to retrieve secret ${secretId}:`, err);
    throw err;
  }
}

// Export a simple sync‑style wrapper for convenience.
// In real code you may want to initialise all needed secrets once at startup.
module.exports = {
  /**
   * Returns the secret synchronously if it is already cached,
   * otherwise resolves a promise.
   *
   * Example usage:
   *   const JWT_SECRET = await config.get('JWT_SECRET');
   */
  get: getSecret,
  // expose whether we loaded a .env (useful for debugging)
  envLoaded,
};
```

### 4. Using the configuration in `app.js`

```js
