### 3.4. Implement Authentication & Authorization

Assuming a JWT‑based approach:

```js
const jwt = require('jsonwebtoken');

// Middleware to verify JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user; // contains payload e.g., { id, role }
    next();
  });
}

// Example of role‑based access
function authorize(allowedRoles) {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      return res.sendStatus(403);
    }
    next();
  };
}

// Protect the /users endpoint
app.get('/users', authenticateToken, authorize(['admin']), (req, res) => {
  // ... existing response ...
});
```

*Why:* Ensures only authenticated and properly authorized principals can access sensitive data.

