### 3.5. Validate Input (Future‑Proof)

If you later add query parameters or request bodies:

```js
const { query, validationResult } = require('express-validator');

app.get(
  '/search',
  [
    query('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('A valid email address is required'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // safe to use req.query.email
  }
);
```

