### 3.6. Structured Error Handling & Logging

```js
const morgan = require('morgan');
app.use(morgan('combined')); // logs to stdout; pipe to log aggregation service

// Central error handler (must be after all routes)
app.use((err, req, res, next) => {
  console.error(err);               // consider a structured logger like Winston
  res.status(500).json({ error: 'Internal Server Error' });
});
```

